INSERT INTO `products` VALUES (1,'Rose Glow Face Cream','A lightweight daily moisturising cream that leaves skin feeling soft and refreshed.',2450.00,'https://images.unsplash.com/photo-1608248543803-ba4f8c70ae0b?auto=format&fit=crop&w=900&q=85',19,1,1),(2,'Hydra Comfort Cream','A comforting cream for a smooth, hydrated-feeling finish.',2850.00,'https://images.unsplash.com/photo-1556229010-6c3f2c9ca5f8?auto=format&fit=crop&w=900&q=85',18,1,1),(3,'Gentle Daily Cleanser','A gentle daily cleanser that helps wash away everyday impurities.',1750.00,'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=900&q=85',25,2,1),(4,'Fresh Foam Face Wash','A refreshing foaming wash for your morning and evening routine.',1950.00,'https://images.unsplash.com/photo-1601049541289-9b1b7bbbfe19?auto=format&fit=crop&w=900&q=85',22,2,1),(5,'Peach Nourish Lip Balm','A pocket-sized lip balm for a soft, comfortable feel.',850.00,'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=900&q=85',29,3,1),(6,'Berry Tint Lip Balm','A subtle berry tint with a smooth balm texture.',950.00,'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=900&q=85',30,3,1),(7,'Blush Rose Nail Colour','A soft rose shade for a simple, polished look.',1250.00,'https://images.unsplash.com/photo-1610992015732-2449b76344bc?auto=format&fit=crop&w=900&q=85',15,4,1),(8,'Classic Red Nail Colour','A classic red nail colour for a bold pop of colour.',1250.00,'https://images.unsplash.com/photo-1632345031435-8727f6897d53?auto=format&fit=crop&w=900&q=85',15,4,1);
