INSERT INTO `therapists` VALUES (1,'Amaya Perera','Senior Beauty Therapist','Amaya specialises in cleansing and facial-care treatments and focuses on a calm, welcoming appointment experience.',5,'https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=900',1,'2026-11-24 11:55:09'),(2,'Nethmi Silva','Beauty Therapist','Nethmi provides facial and hair-care treatments and enjoys helping customers choose a suitable service.',3,'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=900',1,'2026-11-24 11:55:09'),(3,'Kavindi Fernando','Nail Technician','Kavindi focuses on manicure and pedicure services with attention to detail and a friendly approach.',4,'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=900',1,'2026-11-24 11:55:09');
